 1	method GenericMax<A>(cmp: (A, A) -> bool, a: array<A>) returns (max: A)
 2	  requires a != null && a.Length > 0
 3	  requires forall x, y :: cmp.requires(x, y)
 4	  requires forall x, y :: cmp(x, y) || cmp(y, x);
 5	  requires forall x, y, z :: cmp(x, y) && cmp(y, z) ==> cmp(x, z);
 6	
 7	  ensures forall x :: 0 <= x < a.Length ==>
 8	    // uncommenting the following line causes the program to verify
 9	    // assume cmp.requires(a[x], max);
10	    cmp(a[x], max)
11	{
12	  max := a[0];
13	  var i := 0;
14	  while i < a.Length
15	    invariant 0 <= i <= (a.Length) + 1
16	    invariant forall x :: 0 <= x < i ==> cmp(a[x], max)
17	  {
18	    if !cmp(a[i], max) {
19	      max := a[i];
20	    }
21	    i := i + 1;
22	  }
23	}
24

